<?php
namespace Tests\Feature\Verification;
use App\Domain\Documents\Enums\DocumentStatus;use App\Domain\Verification\Enums\VerificationStage;use App\Domain\Verification\Services\VerificationWorkflow;use App\Models\{Document,DocumentVersion,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class VerificationWorkflowTest extends TestCase{use RefreshDatabase;public function test_version_creator_cannot_approve_own_version():void{$this->seed();$u=User::factory()->create();$doc=Document::factory()->create(['status'=>DocumentStatus::PendingQc,'registered_by'=>$u->id]);$version=DocumentVersion::create(['document_id'=>$doc->id,'version_number'=>1,'change_reason'=>'TEST','created_by'=>$u->id]);$doc->update(['current_version_id'=>$version->id]);$v=app(VerificationWorkflow::class)->currentOrCreate($doc->fresh(),VerificationStage::QualityCheck);$this->expectException(\RuntimeException::class);app(VerificationWorkflow::class)->approve($v->fresh('version'),$u->id);}}
